+const fs = require('node:fs');
+const path = require('node:path');
+const files = [];
+function collect(target) {
+  const st = fs.lstatSync(target);
+  if (st.isDirectory()) {
+    for (const name of fs.readdirSync(target)) collect(path.join(target, name));
+  } else if (st.isFile() && target.endsWith('.md')) files.push(target);
+}
+for (const root of ['docs', 'README.md', 'AGENTS.md', 'CHANGELOG.md', '.agents']) collect(root);
+const slug = text => text.toLowerCase().replace(/[^a-z0-9 _-]/g, '').replace(/ /g, '-');
+const headings = new Map();
+const failures = [];
+let links = 0;
+for (const file of files) {
+  let fence = '';
+  for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
+    const trimmed = line.trimStart();
+    if (trimmed.startsWith('```')) { fence = fence === 'ticks' ? '' : 'ticks'; continue; }
+    if (trimmed.startsWith('~~~')) { fence = fence === 'tildes' ? '' : 'tildes'; continue; }
+    if (fence) continue;
+    for (const match of line.matchAll(/\]\(([^)]+)\)/g)) {
+      const link = match[1];
+      if (/^(https?:\/\/|mailto:)/.test(link)) continue;
+      links++;
+      const hash = link.indexOf('#');
+      const target = hash < 0 ? link : link.slice(0, hash);
+      const anchor = hash < 0 ? '' : link.slice(hash + 1);
+      const dest = target ? path.join(path.dirname(file), target) : file;
+      if (target && !fs.existsSync(dest)) { failures.push({file, link, reason: 'missing file'}); continue; }
+      if (anchor && fs.existsSync(dest) && fs.statSync(dest).isFile() && dest.endsWith('.md')) {
+        if (!headings.has(dest)) {
+          headings.set(dest, new Set(fs.readFileSync(dest, 'utf8').split(/\r?\n/)
+            .filter(row => /^#{1,6} /.test(row)).map(row => slug(row.replace(/^#{1,6} +/, '')))));
+        }
+        if (!headings.get(dest).has(anchor)) failures.push({file, link, reason: 'missing heading'});
+      }
+    }
+  }
+}
+const result = {files: files.length, relativeLinks: links, failures};
+fs.writeFileSync('.turbo/entire-publication-links.json', JSON.stringify(result, null, 2));
+process.stdout.write(JSON.stringify(result) + '\n');
+if (failures.length || files.length === 0 || links === 0) process.exitCode = 1;
*** End Patch"));
